select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5939,"materia":"port","nivel":2,"enunciado":"Qual frase segue a norma-padrão?","opcoes":["É proibida a entrada de civis.","É proibida entrada de civis.","É proibido a entrada de civis.","São proibido a entrada de civis."],"explicacao":"Com artigo, o adjetivo concorda: proibida a entrada; sem artigo, é proibido entrada."},{"id":5940,"materia":"port","nivel":3,"enunciado":"Em qual frase a palavra “meio” está correta?","opcoes":["A porta da viatura estava meio aberta.","A porta da viatura estava meia aberta.","Já era meio-dia e meio.","Comprou meio dúzia de coletes."],"explicacao":"Como advérbio (um pouco), “meio” é invariável."},{"id":5941,"materia":"port","nivel":2,"enunciado":"No sentido de “ver”, qual frase usa corretamente o verbo assistir?","opcoes":["Os agentes assistiram ao vídeo da câmera.","Os agentes assistiram o vídeo da câmera.","Os agentes assistiram no vídeo da câmera.","Os agentes assistiram com o vídeo da câmera."],"explicacao":"Assistir (ver) exige a preposição “a”."},{"id":5942,"materia":"port","nivel":1,"enunciado":"Qual frase está correta quanto à regência?","opcoes":["Todos devem obedecer ao regulamento.","Todos devem obedecer o regulamento.","Todos devem obedecer do regulamento.","Todos devem obedecer pelo regulamento."],"explicacao":"Quem obedece, obedece a algo."},{"id":5943,"materia":"port","nivel":2,"enunciado":"Qual frase usa corretamente o verbo “preferir”?","opcoes":["Prefiro investigar a ficar parado.","Prefiro mais investigar do que ficar parado.","Prefiro investigar do que ficar parado.","Prefiro muito mais investigar que ficar parado."],"explicacao":"Prefere-se uma coisa a outra, sem “mais” e sem “do que”."},{"id":5944,"materia":"port","nivel":3,"enunciado":"No sentido de “acarretar”, qual frase está correta?","opcoes":["A falta grave implica punição.","A falta grave implica em punição.","A falta grave implica na punição.","A falta grave implica com punição."],"explicacao":"Implicar (acarretar) é transitivo direto."},{"id":5945,"materia":"port","nivel":2,"enunciado":"Em qual frase a crase está correta?","opcoes":["Refiro-me àquela viatura branca.","Refiro-me à esse policial.","Refiro-me à ele.","Refiro-me à você."],"explicacao":"“Àquela” = a (preposição) + aquela. Não há crase antes de pronome pessoal nem de “esse”."},{"id":5946,"materia":"port","nivel":1,"enunciado":"Qual frase está correta?","opcoes":["O plantão começa às 8 horas.","O plantão começa as 8 horas.","O plantão começa á 8 horas.","O plantão começa à 8 horas."],"explicacao":"Antes de horas determinadas, há crase."},{"id":5947,"materia":"port","nivel":1,"enunciado":"Em qual frase NÃO há crase?","opcoes":["A partir de hoje, a ronda muda.","Fui à delegacia ontem.","Voltou às pressas.","Chegou à uma hora."],"explicacao":"Não há crase antes de verbo (partir)."},{"id":5948,"materia":"port","nivel":2,"enunciado":"Com o pronome “Vossa Excelência”, o verbo fica:","opcoes":["Na 3ª pessoa: “Vossa Excelência decidiu”","Na 2ª pessoa: “Vossa Excelência decidistes”","Na 1ª pessoa: “Vossa Excelência decidi”","Sempre no plural"],"explicacao":"Os pronomes de tratamento levam o verbo à 3ª pessoa."},{"id":5949,"materia":"port","nivel":1,"enunciado":"Qual frase está pontuada corretamente?","opcoes":["O policial prendeu o suspeito.","O policial, prendeu o suspeito.","O policial prendeu, o suspeito.","O, policial prendeu o suspeito."],"explicacao":"Não se separa o sujeito do verbo, nem o verbo do complemento, com vírgula."},{"id":5950,"materia":"port","nivel":1,"enunciado":"Complete: “O juiz expediu o ___ de prisão.”","opcoes":["mandado","mandato","mandatário","mandante"],"explicacao":"Mandado é a ordem judicial; mandato é o período de um cargo eletivo."},{"id":5951,"materia":"port","nivel":1,"enunciado":"Complete: “A polícia combate o ___ de drogas.”","opcoes":["tráfico","tráfego","tráfeco","trafego"],"explicacao":"Tráfico é comércio ilegal; tráfego é o trânsito."},{"id":5952,"materia":"port","nivel":1,"enunciado":"Complete: “O ___ da viatura ficou pronto.”","opcoes":["conserto","concerto","consérto","concertos"],"explicacao":"Conserto é reparo; concerto é apresentação musical."},{"id":5953,"materia":"port","nivel":2,"enunciado":"“O juiz ___ o pedido de liberdade.” Para dizer que ele o aceitou, usa-se:","opcoes":["deferiu","diferiu","deferio","diferenciou"],"explicacao":"Deferir é atender; diferir é adiar ou diferenciar."},{"id":5954,"materia":"port","nivel":2,"enunciado":"Em “Confessou o crime; logo, foi preso”, a palavra “logo” indica:","opcoes":["Conclusão","Oposição","Tempo","Finalidade"],"explicacao":"“Logo” liga uma consequência ao que foi dito."},{"id":5955,"materia":"port","nivel":2,"enunciado":"Qual frase usa corretamente o pronome “cujo”?","opcoes":["O réu cujo advogado faltou foi ouvido.","O réu cujo o advogado faltou foi ouvido.","O réu que o advogado dele faltou foi ouvido.","O réu cujo qual advogado faltou foi ouvido."],"explicacao":"“Cujo” não admite artigo depois dele."},{"id":5956,"materia":"port","nivel":2,"enunciado":"Qual frase usa corretamente “em vez de”?","opcoes":["Em vez de prender, o policial advertiu.","Em vez de subir, o elevador ao invés desceu.","Ao invés de prender, preferiu prender.","Em vez de de prender, advertiu."],"explicacao":"“Em vez de” indica substituição; “ao invés de”, oposição."},{"id":5957,"materia":"port","nivel":3,"enunciado":"Na frase “Prenderam-se os suspeitos”, o verbo está na:","opcoes":["Voz passiva sintética","Voz ativa","Voz reflexiva","Voz passiva analítica"],"explicacao":"Equivale a “Os suspeitos foram presos”."},{"id":5958,"materia":"rl","nivel":0,"enunciado":"Uma equipe de 12 policiais é dividida igualmente em 3 viaturas. Quantos policiais vão em cada viatura?","opcoes":["4","3","6","9"],"explicacao":"12 ÷ 3 = 4."},{"id":5959,"materia":"rl","nivel":2,"enunciado":"Um suspeito andou 3 km para o norte e depois 4 km para o leste. A que distância, em linha reta, está do ponto de partida?","opcoes":["5 km","7 km","1 km","12 km"],"explicacao":"Teorema de Pitágoras: 3² + 4² = 5²."},{"id":5960,"materia":"rl","nivel":1,"enunciado":"Dos 120 presos de uma unidade, 30 são reincidentes. Que porcentagem isso representa?","opcoes":["25%","30%","20%","40%"],"explicacao":"30 ÷ 120 = 0,25."},{"id":5961,"materia":"rl","nivel":3,"enunciado":"O efetivo de uma delegacia aumentou 10% em um ano e mais 10% no ano seguinte. O aumento total foi de:","opcoes":["21%","20%","10%","11%"],"explicacao":"1,1 × 1,1 = 1,21."},{"id":5962,"materia":"rl","nivel":1,"enunciado":"Uma viatura anda a 80 km/h. Em 45 minutos, ela percorre:","opcoes":["60 km","45 km","80 km","35 km"],"explicacao":"45 min = 3/4 de hora; 80 × 3/4 = 60."},{"id":5963,"materia":"rl","nivel":3,"enunciado":"“Se chove, não há ronda” é equivalente a:","opcoes":["Não chove ou não há ronda","Chove e há ronda","Se não chove, há ronda","Chove ou há ronda"],"explicacao":"P → Q equivale a ¬P ∨ Q."},{"id":5964,"materia":"rl","nivel":2,"enunciado":"Um cadeado tem 3 dígitos, de 0 a 9, que podem se repetir. Quantas combinações existem?","opcoes":["1.000","720","30","999"],"explicacao":"10 × 10 × 10 = 1.000."},{"id":5965,"materia":"rl","nivel":1,"enunciado":"Entre 10 suspeitos, 4 têm tatuagem. Escolhendo um ao acaso, qual a chance de ele NÃO ter tatuagem?","opcoes":["60%","40%","4%","6%"],"explicacao":"6 em 10 não têm tatuagem."},{"id":5966,"materia":"rl","nivel":2,"enunciado":"Qual é o próximo número da sequência 2, 5, 11, 23, ...?","opcoes":["47","46","35","44"],"explicacao":"Cada termo é o dobro do anterior mais 1."},{"id":5967,"materia":"rl","nivel":1,"enunciado":"Uma operação começou às 22h45 e durou 1h30. A que horas terminou?","opcoes":["0h15","23h15","23h45","1h15"],"explicacao":"22h45 + 1h30 = 24h15, ou seja, 0h15."},{"id":5968,"materia":"rl","nivel":0,"enunciado":"Se 15 de março caiu numa sexta-feira, 22 de março caiu numa:","opcoes":["Sexta-feira","Quinta-feira","Sábado","Segunda-feira"],"explicacao":"Sete dias depois, mesmo dia da semana."},{"id":5969,"materia":"rl","nivel":2,"enunciado":"Numa operação, a razão entre presos e liberados foi de 3 para 1. Se havia 40 pessoas, quantas foram presas?","opcoes":["30","10","13","27"],"explicacao":"40 ÷ 4 = 10; 3 × 10 = 30."},{"id":5970,"materia":"rl","nivel":2,"enunciado":"Numa turma, 20 agentes falam inglês, 15 falam espanhol e 5 falam os dois. Quantos falam pelo menos uma dessas línguas?","opcoes":["30","35","40","25"],"explicacao":"20 + 15 - 5 = 30."},{"id":5971,"materia":"rl","nivel":4,"enunciado":"Qual é o menor número de pessoas para garantir que duas façam aniversário no mesmo mês?","opcoes":["13","12","2","24"],"explicacao":"Princípio da casa dos pombos: 12 meses + 1."},{"id":5972,"materia":"rl","nivel":3,"enunciado":"De 5 policiais, de quantas formas se escolhem um motorista e um copiloto?","opcoes":["20","10","25","5"],"explicacao":"Arranjo: 5 × 4 = 20 (a ordem importa)."},{"id":5973,"materia":"inf","nivel":1,"enunciado":"No Windows, a tecla Windows + L serve para:","opcoes":["Bloquear o computador","Abrir o Explorador de Arquivos","Desligar o monitor","Abrir a lixeira"],"explicacao":"Útil ao sair de perto da máquina."},{"id":5974,"materia":"inf","nivel":3,"enunciado":"No Excel, se A1 contém “Polícia” e B1 contém “Civil”, a fórmula =A1&\" \"&B1 retorna:","opcoes":["Polícia Civil","PolíciaCivil","#VALOR!","A1 B1"],"explicacao":"O & junta (concatena) textos."},{"id":5975,"materia":"inf","nivel":1,"enunciado":"No endereço https://www.gov.br, a parte “https” indica o:","opcoes":["Protocolo","Domínio","Servidor de e-mail","Nome do arquivo"],"explicacao":"HTTPS é o protocolo seguro da web."},{"id":5976,"materia":"inf","nivel":0,"enunciado":"Um site terminado em “.gov.br” pertence, em regra, a:","opcoes":["Órgão do governo brasileiro","Empresa privada","Universidade estrangeira","Organização militar dos EUA"],"explicacao":".edu.br indica educação; .com.br, comércio."},{"id":5977,"materia":"inf","nivel":1,"enunciado":"Ligar para alguém fingindo ser do suporte técnico para conseguir sua senha é um exemplo de:","opcoes":["Engenharia social","Backup","Criptografia","Firewall"],"explicacao":"Explora a confiança das pessoas, não falhas técnicas."},{"id":5978,"materia":"inf","nivel":1,"enunciado":"A rede interna de uma instituição, acessível só aos funcionários, é a:","opcoes":["Intranet","Internet","Extranet pública","Deep web"],"explicacao":"Usa as mesmas tecnologias da internet, mas é restrita."},{"id":5979,"materia":"pen","nivel":2,"enunciado":"Uma pessoa faminta furta um pão para não morrer de fome. Esse “furto famélico” pode ser justificado pelo:","opcoes":["Estado de necessidade","Arrependimento posterior","Exercício regular de direito","Erro de proibição"],"explicacao":"Há perigo atual à vida, que não provocou."},{"id":5980,"materia":"pen","nivel":2,"enunciado":"Furtar um chiclete de R$ 1 de um supermercado pode levar à aplicação do princípio da:","opcoes":["Insignificância","Legalidade","Anterioridade","Individualização da pena"],"explicacao":"Afasta a tipicidade material quando a lesão é ínfima."},{"id":5981,"materia":"pen","nivel":4,"enunciado":"Pela Súmula 567 do STJ, o sistema de vigilância ou de segurança no estabelecimento comercial:","opcoes":["Não torna, por si só, impossível o furto","Sempre torna impossível o furto","Transforma o furto em roubo","Exclui a culpabilidade do agente, que foi filmado o tempo todo"],"explicacao":"Súmula 567 do STJ."},{"id":5982,"materia":"pen","nivel":3,"enunciado":"Depois de subtrair a carteira, o ladrão empurra a vítima para garantir a fuga com o bem. Ele comete:","opcoes":["Roubo impróprio","Furto qualificado","Roubo próprio","Lesão corporal"],"explicacao":"Art. 157, § 1º: a violência vem depois da subtração."},{"id":5983,"materia":"pen","nivel":2,"enunciado":"Comprar um celular novo por R$ 50, sem nota, de um desconhecido na rua, pode configurar:","opcoes":["Receptação culposa","Estelionato","Furto","Nenhum crime"],"explicacao":"Art. 180, § 3º: pelo preço e pelas condições, deveria presumir a origem criminosa."},{"id":5984,"materia":"pen","nivel":3,"enunciado":"O motorista que faz “racha” em via movimentada, assumindo o risco de matar, e mata alguém, age com:","opcoes":["Dolo eventual","Culpa inconsciente","Culpa consciente","Caso fortuito"],"explicacao":"Ele não quer o resultado, mas aceita o risco de produzi-lo."},{"id":5985,"materia":"pen","nivel":3,"enunciado":"O salva-vidas de plantão que, podendo agir, deixa um banhista se afogar responde por:","opcoes":["Homicídio, por omissão imprópria","Omissão de socorro apenas, com pena aumentada pela morte","Nenhum crime","Abandono de incapaz"],"explicacao":"Art. 13, § 2º: quem tem o dever de agir responde pelo resultado."},{"id":5986,"materia":"pen","nivel":2,"enunciado":"Quem empresta sua arma a um amigo, sabendo que ele vai usá-la para matar alguém, é:","opcoes":["Partícipe do homicídio","Autor de omissão de socorro","Isento de pena","Autor apenas de porte ilegal"],"explicacao":"Art. 29 do Código Penal: concorre para o crime."},{"id":5987,"materia":"pen","nivel":1,"enunciado":"Entrar à noite no quintal do vizinho, contra a vontade dele, é crime de:","opcoes":["Violação de domicílio","Furto tentado","Ameaça","Dano"],"explicacao":"Art. 150: o quintal integra a casa."},{"id":5988,"materia":"pen","nivel":0,"enunciado":"Mandar mensagem pelo WhatsApp dizendo “vou te matar” a alguém pode configurar:","opcoes":["Crime de ameaça","Nada, pois foi por mensagem","Apenas falta de educação","Calúnia"],"explicacao":"A ameaça pode ser por palavra, escrito ou gesto."},{"id":5989,"materia":"pen","nivel":3,"enunciado":"A injúria contra pessoa idosa ou com deficiência, com elementos ligados a essa condição, tem pena de:","opcoes":["Reclusão de 1 a 3 anos e multa","Detenção de 1 a 6 meses, ou multa, como na injúria simples","Apenas multa","Advertência"],"explicacao":"Art. 140, § 3º, do Código Penal."},{"id":5990,"materia":"ppen","nivel":3,"enunciado":"O juiz das garantias é responsável:","opcoes":["Pelo controle da legalidade da investigação","Pelo julgamento do mérito e pela sentença do processo","Pela execução da pena","Pela defesa do réu"],"explicacao":"Arts. 3º-A a 3º-F do CPP."},{"id":5991,"materia":"ppen","nivel":3,"enunciado":"Se o delegado indeferir o pedido de abertura de inquérito feito pela vítima, cabe recurso:","opcoes":["Ao chefe de polícia","Ao STF","Ao Tribunal do Júri","À Defensoria"],"explicacao":"Art. 5º, § 2º, do CPP."},{"id":5992,"materia":"ppen","nivel":2,"enunciado":"À noite, o próprio morador autoriza a entrada da polícia em sua casa. A entrada é:","opcoes":["Válida, pois houve consentimento","Ilegal, pois é noite","Válida só com ordem judicial expedida antes da diligência","Válida só se houver flagrante"],"explicacao":"O consentimento do morador permite a entrada a qualquer hora."},{"id":5993,"materia":"ppen","nivel":4,"enunciado":"Na lesão corporal, para provar a incapacidade por mais de 30 dias, faz-se:","opcoes":["Exame complementar, logo após o 30º dia","Novo inquérito","Interrogatório do réu sobre a gravidade das lesões","Acareação"],"explicacao":"Art. 168, § 2º, do CPP."},{"id":5994,"materia":"leg","nivel":3,"enunciado":"Pela Lei Maria da Penha, a vítima deve ser notificada:","opcoes":["Dos atos processuais relativos ao agressor, especialmente sua entrada e saída da prisão","Apenas da sentença final","Só se pedir por escrito","Nunca, para preservar a intimidade e a segurança do agressor durante o processo"],"explicacao":"Art. 21 da Lei 11.340/2006."},{"id":5995,"materia":"leg","nivel":2,"enunciado":"Pela Lei Maria da Penha, a mulher em situação de violência deve ser atendida:","opcoes":["Preferencialmente por servidoras do sexo feminino","Só por policiais homens","Só pelo juiz da Vara de Violência Doméstica, pessoalmente","Só pela família"],"explicacao":"Art. 10-A da Lei 11.340/2006."},{"id":5996,"materia":"leg","nivel":1,"enunciado":"O tráfico de drogas, pela Constituição, é crime:","opcoes":["Inafiançável e insuscetível de graça ou anistia","Afiançável","De menor potencial ofensivo","Imprescritível"],"explicacao":"Art. 5º, XLIII."},{"id":5997,"materia":"leg","nivel":2,"enunciado":"Pelo Estatuto da Pessoa Idosa, entre os idosos, têm prioridade especial os maiores de:","opcoes":["80 anos","65 anos","70 anos","90 anos"],"explicacao":"Art. 3º, § 2º, da Lei 10.741/2003."},{"id":5998,"materia":"const","nivel":1,"enunciado":"Pela Constituição, a Polícia Federal apura infrações penais contra:","opcoes":["Bens, serviços e interesses da União","Bens dos municípios","Interesses particulares de grandes empresas e bancos","Bens dos estados apenas"],"explicacao":"Art. 144, § 1º, I."},{"id":5999,"materia":"const","nivel":1,"enunciado":"Pela Constituição, além das atribuições definidas em lei, os corpos de bombeiros militares executam:","opcoes":["Atividades de defesa civil","Investigações criminais","Patrulhamento de rodovias federais","Policiamento de fronteiras"],"explicacao":"Art. 144, § 5º."},{"id":6000,"materia":"const","nivel":0,"enunciado":"Pela Constituição, é livre a manifestação do pensamento, sendo vedado:","opcoes":["O anonimato","O uso das redes sociais","A crítica ao governo","A opinião política"],"explicacao":"Art. 5º, IV."},{"id":6001,"materia":"const","nivel":2,"enunciado":"Pela Constituição, é assegurado o direito de resposta:","opcoes":["Proporcional ao agravo, além da indenização","Só para autoridades","Só em jornais impressos e emissoras de rádio e televisão","Sem direito a indenização"],"explicacao":"Art. 5º, V."},{"id":6002,"materia":"const","nivel":1,"enunciado":"Pela Constituição, o sigilo da correspondência é:","opcoes":["Inviolável","Livre para a polícia","Só garantido aos brasileiros","Inexistente"],"explicacao":"Art. 5º, XII."},{"id":6003,"materia":"adm","nivel":3,"enunciado":"A diferença entre motivo e motivação do ato administrativo é que a motivação:","opcoes":["É a exposição por escrito dos motivos","É o resultado do ato","É a autoridade competente que o pratica e assina","É a forma do ato"],"explicacao":"O motivo é o fato e o direito que justificam o ato."},{"id":6004,"materia":"adm","nivel":1,"enunciado":"O servidor que pede para sair do cargo é:","opcoes":["Exonerado a pedido","Demitido","Cassado","Destituído"],"explicacao":"Demissão é punição; exoneração, não."},{"id":6005,"materia":"adm","nivel":2,"enunciado":"O teto da remuneração no serviço público é o subsídio dos:","opcoes":["Ministros do STF","Deputados estaduais","Governadores, sempre","Prefeitos"],"explicacao":"Art. 37, XI, com subtetos nos estados e municípios."},{"id":6006,"materia":"dh","nivel":0,"enunciado":"Pela Declaração Universal dos Direitos Humanos, ninguém será mantido em:","opcoes":["Escravidão ou servidão","Liberdade","Seu próprio país","Sua religião"],"explicacao":"Artigo 4 da Declaração."},{"id":6007,"materia":"cont","nivel":2,"enunciado":"Pela LGPD, o órgão federal que fiscaliza o cumprimento da lei é a:","opcoes":["ANPD","Anatel","Aneel","ANS"],"explicacao":"Autoridade Nacional de Proteção de Dados."},{"id":6008,"materia":"port","nivel":1,"enunciado":"Em “O golpista ludibriou a vítima”, “ludibriou” significa:","opcoes":["Enganou","Ajudou","Agrediu","Seguiu"],"explicacao":"Ludibriar é enganar, iludir."},{"id":6009,"materia":"port","nivel":2,"enunciado":"Em “O uso de drogas é pernicioso à saúde”, “pernicioso” significa:","opcoes":["Prejudicial","Indiferente","Benéfico","Comum"],"explicacao":"Pernicioso é o que faz mal."},{"id":6010,"materia":"port","nivel":2,"enunciado":"Em “A vítima saiu incólume do acidente”, “incólume” significa:","opcoes":["Ilesa","Ferida","Assustada","Inconsciente"],"explicacao":"Incólume é sem ferimentos."},{"id":6011,"materia":"port","nivel":3,"enunciado":"Em “Era um infrator contumaz”, “contumaz” significa:","opcoes":["Que insiste no erro; reincidente","Arrependido","Primário","Inocente"],"explicacao":"Contumaz é obstinado, que persiste."},{"id":6012,"materia":"port","nivel":2,"enunciado":"O antônimo de “ostensivo” é:","opcoes":["Discreto","Visível","Evidente","Público"],"explicacao":"Policiamento ostensivo é o que se mostra, visível."},{"id":6013,"materia":"port","nivel":1,"enunciado":"Complete: “O IBGE fez o ___ da população.”","opcoes":["censo","senso","sensso","cemso"],"explicacao":"Censo é recenseamento; senso é juízo."},{"id":6014,"materia":"port","nivel":0,"enunciado":"Complete: “O policial foi até a casa para o ___ do mandado.”","opcoes":["cumprimento","comprimento","cumprimeto","comprimeto"],"explicacao":"Comprimento é medida de tamanho."},{"id":6015,"materia":"port","nivel":0,"enunciado":"Complete: “Avançar o sinal vermelho é uma ___ de trânsito.”","opcoes":["infração","inflação","enfração","infraçam"],"explicacao":"Inflação é a alta geral dos preços."},{"id":6016,"materia":"port","nivel":1,"enunciado":"Pela norma-padrão, qual frase usa corretamente o verbo “chegar”?","opcoes":["Chegamos à delegacia às 8h.","Chegamos na delegacia às 8h.","Chegamos para a delegacia às 8h.","Chegamos com a delegacia às 8h."],"explicacao":"Pela norma-padrão, quem chega, chega a algum lugar."},{"id":6017,"materia":"port","nivel":3,"enunciado":"Qual frase usa corretamente o verbo “esquecer”?","opcoes":["Esqueci-me do depoimento.","Esqueci-me o depoimento.","Esqueci do depoimento, segundo a norma-padrão.","Me esqueci o depoimento."],"explicacao":"Esquecer-se de; ou esquecer algo, sem preposição."},{"id":6018,"materia":"port","nivel":1,"enunciado":"Em qual frase a vírgula está bem empregada?","opcoes":["Investigou muito, mas não achou provas.","Investigou muito mas, não achou provas.","Investigou, muito mas não achou provas.","Investigou muito mas não, achou provas."],"explicacao":"Usa-se vírgula antes do “mas”."},{"id":6019,"materia":"port","nivel":2,"enunciado":"Com o documento nas próprias mãos, o delegado diz: “___ documento é falso.”","opcoes":["Este","Esse","Aquele","Aquilo"],"explicacao":"“Este” indica o que está perto de quem fala."},{"id":6020,"materia":"rl","nivel":0,"enunciado":"Uma bota de R$ 80,00 tem desconto de 25%. Quanto ela custa com desconto?","opcoes":["R$ 60,00","R$ 55,00","R$ 65,00","R$ 75,00"],"explicacao":"25% de 80 = 20; 80 - 20 = 60."},{"id":6021,"materia":"rl","nivel":0,"enunciado":"Quanto é 3/5 de 200 inquéritos?","opcoes":["120","60","100","150"],"explicacao":"200 ÷ 5 × 3 = 120."},{"id":6022,"materia":"rl","nivel":0,"enunciado":"Um plantão de 24 horas começou às 8h de sábado. Ele termina:","opcoes":["Às 8h de domingo","Às 20h de sábado","Às 8h de segunda","Às 20h de domingo"],"explicacao":"24 horas depois, mesmo horário do dia seguinte."},{"id":6023,"materia":"rl","nivel":1,"enunciado":"Quantos múltiplos de 5 existem de 1 a 50?","opcoes":["10","5","9","11"],"explicacao":"5, 10, 15, ..., 50: 10 números."},{"id":6024,"materia":"rl","nivel":1,"enunciado":"“Não é verdade que o suspeito não fugiu” equivale a:","opcoes":["O suspeito fugiu","O suspeito não fugiu","O suspeito talvez tenha fugido","Ninguém fugiu"],"explicacao":"A dupla negação afirma."},{"id":6025,"materia":"rl","nivel":2,"enunciado":"Lançando uma moeda duas vezes, qual a probabilidade de sair cara nas duas?","opcoes":["1/4","1/2","1/3","2/3"],"explicacao":"1/2 × 1/2 = 1/4."},{"id":6026,"materia":"rl","nivel":3,"enunciado":"De quantas formas se pode montar uma comissão de 3 agentes entre 5?","opcoes":["10","15","60","20"],"explicacao":"C(5,3) = 10; a ordem não importa."},{"id":6027,"materia":"inf","nivel":0,"enunciado":"Um arquivo com extensão .mp4 é, normalmente:","opcoes":["Um vídeo","Uma planilha","Um texto","Um programa"],"explicacao":".mp3 é áudio."},{"id":6028,"materia":"pen","nivel":3,"enunciado":"O pai que, por descuido, atropela e mata o próprio filho pode receber do juiz:","opcoes":["Perdão judicial, se as consequências o atingirem gravemente","Pena dobrada","Pena de homicídio doloso","Prisão preventiva obrigatória, por ter causado a morte de alguém"],"explicacao":"Art. 121, § 5º, do Código Penal."},{"id":6029,"materia":"pen","nivel":3,"enunciado":"Numa briga, um homem dá um soco no outro, que cai, bate a cabeça e morre. Sem querer nem assumir o risco da morte, ele responde por:","opcoes":["Lesão corporal seguida de morte","Homicídio doloso","Homicídio qualificado","Latrocínio"],"explicacao":"Crime preterdoloso: dolo na lesão e culpa na morte (art. 129, § 3º)."},{"id":6030,"materia":"pen","nivel":0,"enunciado":"Quebrar de propósito o celular de outra pessoa é crime de:","opcoes":["Dano","Furto","Roubo","Estelionato"],"explicacao":"Art. 163 do Código Penal."},{"id":6031,"materia":"pen","nivel":3,"enunciado":"A lesão corporal praticada contra a mulher por razões da condição do sexo feminino tem pena de:","opcoes":["Reclusão de 2 a 5 anos","Detenção de 3 meses a 1 ano","Apenas multa","Advertência"],"explicacao":"Art. 129, § 13, do Código Penal."},{"id":6032,"materia":"ppen","nivel":4,"enunciado":"O interrogatório do réu preso por videoconferência é:","opcoes":["Excepcional, por decisão fundamentada do juiz","A regra em todos os casos, para economizar com a escolta","Proibido","Escolha do delegado"],"explicacao":"Art. 185, § 2º, do CPP."},{"id":6033,"materia":"ppen","nivel":3,"enunciado":"A vítima pode se retratar da representação:","opcoes":["Até o oferecimento da denúncia","Até a sentença","A qualquer tempo","Nunca"],"explicacao":"Art. 25 do CPP."},{"id":6034,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Drogas, entregar droga a outra pessoa de graça:","opcoes":["Também é tráfico","Não é crime, porque não houve venda","É só uso","É contravenção"],"explicacao":"O art. 33 pune fornecer, ainda que gratuitamente."},{"id":6035,"materia":"const","nivel":1,"enunciado":"Pela Constituição, em tempo de paz, a locomoção no território nacional é:","opcoes":["Livre, nos termos da lei","Proibida sem autorização","Livre só para brasileiros natos","Permitida só de dia"],"explicacao":"Art. 5º, XV."},{"id":6036,"materia":"const","nivel":1,"enunciado":"Entre os princípios do Brasil nas relações internacionais, a Constituição prevê a concessão de:","opcoes":["Asilo político","Extradição de brasileiros natos","Pena de morte a estrangeiros","Banimento"],"explicacao":"Art. 4º, X."},{"id":6037,"materia":"const","nivel":0,"enunciado":"Pela Constituição, ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de:","opcoes":["Lei","Ordem de qualquer autoridade","Costume local","Decisão da maioria"],"explicacao":"Art. 5º, II: princípio da legalidade."},{"id":6038,"materia":"adm","nivel":2,"enunciado":"O servidor reprovado na avaliação do estágio probatório será:","opcoes":["Exonerado ou reconduzido ao cargo anterior, se estável","Demitido por justa causa, após processo administrativo disciplinar","Mantido no cargo","Aposentado"],"explicacao":"Art. 20, § 2º, da Lei 8.112/1990."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
